for msg in msgs:
 for n in range(1,8):
  pat=rf'Demo pair {n} input \(\d+x\d+\):\n(.*?)\nDemo pair {n} output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance|\Z)'
  m=re.search(pat,msg,re.S)
  if m:
   def grid(s): return [list(map(int,l.split())) for l in s.strip().splitlines()]
   pairs[n]=(grid(m.group(1)),grid(m.group(2)))
print('pairs parsed', sorted(pairs))

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c0 in range(w):
   col=g[r][c0]
   if col==next((g[0][0],),None): pass
   if (r,c0) in seen or col==min(set(sum(g,[]))): continue
   q=[(r,c0)]; seen.add((r,c0)); cells=[]
   while q:
    a,b=q.pop(); cells.append((a,b))
    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and g[x][y]==col: seen.add((x,y));q.append((x,y))
