import sqlite3,re,collections
p='/home/USER/continual-arc-baselines/.workbench/stage1/H0-hermes-luna6-medium-rnd0/frozen/seen/play/users/u070/system/state/hermes/state.db'; c=sqlite3.connect(p); sid='ac16275b-12c6-4578-a59d-1e0cde4273ca'
rows=c.execute("select id,content from messages where session_id=? and role='user' order by id",(sid,)).fetchall()
def parse_grid(text,label):
 m=re.search(re.escape(label)+r" \((\d+)x(\d+)\):\n((?:[0-9 ]+\n?)+)",text)
 if not m:return None
 return [list(map(int,line.split())) for line in m.group(3).strip().splitlines()]
def comps(g):
 R,C=len(g),len(g[0]); bg=collections.Counter(v for row in g for v in row).most_common(1)[0][0]; seen=set(); out=[]
 for r in range(R):
  for q in range(C):
   if (r,q) in seen or g[r][q]==bg:continue
   col=g[r][q]; stack=[(r,q)]; seen.add((r,q)); cells=[]
   while stack:
    a,b=stack.pop(); cells.append((a,b))
    for z in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=z[0]<R and 0<=z[1]<C and z not in seen and g[z[0]][z[1]]==col:seen.add(z);stack.append(z)
   out.append((col,cells))
 return bg,out
for i,t in rows:
 if 'Demo pair' not in (t or ''):continue
 n=int(re.search(r'Demo pair (\d+)',t).group(1)); a=parse_grid(t,f'Demo pair {n} input'); b=parse_grid(t,f'Demo pair {n} output')
 if a is None or b is None: print(n,'parse fail');continue
 dif=[(r,q,a[r][q],b[r][q]) for r in range(len(a)) for q in range(len(a[0])) if a[r][q]!=b[r][q]]
 print('\nDEMO',n,'dims',len(a),len(a[0]),'diff',dif)
 bg,cs=comps(a); print('bg',bg,'components:',[(col,len(cells),(min(r for r,q in cells),min(q for r,q in cells),max(r for r,q in cells),max(q for r,q in cells)),''.join('' for _ in [])) for col,cells in cs])
 if dif:
  col=dif[0][2]; cells=next((cells for c2,cells in cs if c2==col and any((r,q) in cells for r,q,_,_ in dif)),None)
  # exact changed component's rows as relative coordinates
  changed={(r,q) for r,q,_,_ in dif};
  tgt=next((cells for c2,cells in cs if any(x in changed for x in cells)),[])
  if tgt:
   r0=min(r for r,q in tgt); q0=min(q for r,q in tgt); print('target color, area',col,len(tgt),'shape','/'.join(''.join('#' if (r0+i,q0+j) in tgt else '.' for j in range(max(q for r,q in tgt)-q0+1)) for i in range(max(r for r,q in tgt)-r0+1)))
